private void capSetup(RegisterCapabilitiesEvent event) {

    ITEMS.getRegistryObjects().values().forEach((holder) -> {

        if (holder.value() instanceof IFluxItem fluxItem) {
            event.registerItem(Capabilities.EnergyStorage.ITEM, (itemStack, context) -> new EnergyContainerItemWrapper(itemStack, fluxItem), holder.value());
        }
        if (holder.value() instanceof FluxArmorItem fluxArmor) {
            event.registerItem(CapabilityFluxShielding.ITEM, (itemStack, context) -> new FluxShieldedEnergyItemWrapper(itemStack, fluxArmor.getEnergyPerUse(true)), holder.value());
        }

        if (holder.value() instanceof FluxAxeItem axe) {
            event.registerItem(CoreCapabilities.AreaEffectHandler.ITEM, (itemStack, context) -> new FluxAxeItem.AreaWrapper(itemStack, axe), holder.value());
        }
        if (holder.value() instanceof FluxExcavatorItem excavator) {
            event.registerItem(CoreCapabilities.AreaEffectHandler.ITEM, (itemStack, context) -> new FluxExcavatorItem.AreaWrapper(itemStack, excavator), holder.value());
        }
        if (holder.value() instanceof FluxHammerItem hammer) {
            event.registerItem(CoreCapabilities.AreaEffectHandler.ITEM, (itemStack, context) -> new FluxHammerItem.AreaWrapper(itemStack, hammer), holder.value());
        }
        if (holder.value() instanceof FluxSickleItem sickle) {
            event.registerItem(CoreCapabilities.AreaEffectHandler.ITEM, (itemStack, context) -> new FluxSickleItem.AreaWrapper(itemStack, sickle), holder.value());
        }
        if (holder.value() instanceof FluxShieldItem shield) {
            event.registerItem(CoreCapabilities.ShieldHandler.ITEM, (itemStack, context) -> new FluxShieldItem.ShieldWrapper(itemStack, shield), holder.value());
        }
        if (holder.value() instanceof FluxBowItem bow) {
            event.registerItem(CoreCapabilities.ArcheryHandler.BOW, (itemStack, context) -> new FluxBowItem.BowWrapper(itemStack, bow), holder.value());
        }
        if (holder.value() instanceof FluxQuiverItem quiver) {
            event.registerItem(CoreCapabilities.ArcheryHandler.AMMO, (itemStack, context) -> new FluxQuiverItem.AmmoWrapper(itemStack, quiver), holder.value());
        }
    });
}

default int getEnergyPerUse(boolean empowered) {

    return empowered ? ENERGY_PER_USE_EMPOWERED : ENERGY_PER_USE;
}

default boolean hasEnergy(ItemStack stack, int amount) {

    return getEnergyStored(stack) >= amount;
}

default boolean useEnergy(ItemStack stack, int amount, boolean simulate) {

    if (simulate) {
        return true;
    }
    if (hasEnergy(stack, amount)) {
        extractEnergy(stack, amount, false);
        return true;
    }
    return false;
}

default boolean useEnergy(ItemStack stack, boolean empowered, @Nullable Entity entity) {

    return useEnergy(stack, getEnergyPerUse(empowered), Utils.isCreativePlayer(entity));
}

default boolean isEmpowered(ItemStack stack) {

    return getMode(stack) > 0;
}

public static void handleLivingAttackEvent(LivingAttackEvent event) {

    if (event.isCanceled()) {
        return;
    }
    LivingEntity target = event.getEntity();
    DamageSource source = event.getSource();
    // Flux Shielding
    float amount = event.getAmount();
    if (amount <= 500.0F && !(target instanceof Player player && (player.isCreative() || player.isSpectator())) && !(source.is(DamageTypeTags.BYPASSES_ARMOR) && source.is(DamageTypeTags.BYPASSES_EFFECTS))) {
        ItemStack shieldedItem = FluxShieldingHelper.findShieldedItem(target);
        if (!shieldedItem.isEmpty()) {
            if (target.invulnerableTime > 0) {
                event.setCanceled(true);
            } else if (FluxShieldingHelper.useFluxShieldCharge(target, shieldedItem)) {
                target.invulnerableTime = 10;
                event.setCanceled(true);
                if (target instanceof ServerPlayer) {
                    FluxShieldingHelper.updateHUD((ServerPlayer) target);
                }
            }
            return;
        }
    }

    // Flux Armor Helmet Damage
    if (source.is(DamageTypeTags.DAMAGES_HELMET)) {
        ItemStack helmet = target.getItemBySlot(EquipmentSlot.HEAD);
        float damage = Math.max(0.5F, amount * 0.25F);
        if (helmet.getItem() instanceof FluxArmorItem armor) {
            int use = Math.min((int) (damage * armor.getEnergyPerUse(false)), armor.getEnergyStored(helmet));
            armor.useEnergy(helmet, use, target);
        }
    }
}

public static void handleLivingHurtEvent(LivingHurtEvent event) {

    if (event.isCanceled()) {
        return;
    }
    // Flux Shielding
    DamageSource source = event.getSource();
    if (source.is(DamageTypeTags.BYPASSES_ARMOR) && source.is(DamageTypeTags.BYPASSES_EFFECTS)) {
        return;
    }
    float amount = event.getAmount();
    if (amount <= 0.0F) {
        return;
    }
    LivingEntity target = event.getEntity();
    if (FluxShieldingHelper.useFluxShieldCharge(target)) {
        event.setAmount(Math.max(amount - 500.0F, 0));
        if (target instanceof ServerPlayer) {
            FluxShieldingHelper.updateHUD((ServerPlayer) target);
        }
    } else if (!source.is(DamageTypeTags.BYPASSES_ARMOR)) { // Flux Armor Damage
        float damage = Math.max(0.5F, amount * 0.25F);
        target.getArmorSlots().forEach(stack -> {
            if (stack.getItem() instanceof FluxArmorItem armor) {
                int use = Math.min((int) (damage * armor.getEnergyPerUse(false)), armor.getEnergyStored(stack));
                armor.useEnergy(stack, use, target);
            }
        });
    }
}

