protected static void onUseFluxShieldCharge(LivingEntity entity) {

    entity.level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), SOUND_SHIELDING_BREAK.get(), entity.getSoundSource(), 1.5F, 0.65F + MathHelper.RANDOM.nextFloat() * 0.2F);
    AABB bounds = entity.getBoundingBox();
    Vec3 pos = bounds.getCenter();
    if (!entity.level.isClientSide) {
        ((ServerLevel) entity.level).sendParticles(DustParticleOptions.REDSTONE, pos.x(), pos.y(), pos.z(), 20, bounds.getXsize() * 0.5 + 0.2, bounds.getYsize() * 0.5 + 0.2, bounds.getZsize() * 0.5 + 0.2, 0);
    }
}

public InteractionResult useOn(UseOnContext context) {

    Player player = context.getPlayer();
    ItemStack stack = context.getItemInHand();
    int energy = getEnergyPerUse(true) * 2;
    if (player == null || !player.onGround() || !isEmpowered(stack) || !(hasEnergy(stack, energy) || player.abilities.instabuild)) {
        return InteractionResult.FAIL;
    }
    Level world = context.getLevel();
    BlockPos pos = context.getClickedPos();
    BlockState state = world.getBlockState(pos);
    if (world.isClientSide) {
        world.playSound(player, pos, state.getSoundType(world, pos, player).getBreakSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
    } else if (world.addFreshEntity(new FluxHammerShockwave(world, Vec3.atBottomCenterOf(pos.above()), player))) {
        useEnergy(stack, energy, player.abilities.instabuild);
        player.getCooldowns().addCooldown(this, getSlamCooldown(stack));
    }
    return InteractionResult.SUCCESS;
}

protected void onHit() {

    if (getOwner() instanceof LivingEntity living) {
        living.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 70, 0));
    }
}

protected DamageSource getDamageSource(Vec3 pos) {

    Entity owner = getOwner();
    DamageSources sources = level.damageSources();
    if (owner instanceof Player player) {
        return Utils.source(sources, DamageTypes.PLAYER_ATTACK, this, player, pos);
    }
    if (owner instanceof LivingEntity living) {
        return Utils.source(sources, DamageTypes.MOB_ATTACK, this, living, pos);
    }
    return Utils.source(sources, DamageTypes.IN_WALL, this, this, pos);
}
